set -euo pipefail
cd /home/ubuntu/apps/travel-planner
.venv/bin/python - <<'PY'
from pathlib import Path
import base64,json,hashlib
data=json.loads('{"rag/eval/reports/optional_departure_v1.json": "", "docs/PLAN_CHAT_NL_INTAKE.md": "", "docs/WEB_TEST_MVP.md": ""}')
for n,b in data.items():Path(n).write_bytes(base64.b64decode(b))
r=json.loads(Path('rag/eval/reports/optional_departure_v1.json').read_text())
for n,h in r['file_sha256'].items():assert hashlib.sha256(Path(n).read_bytes()).hexdigest()==h,n
print('Optional departure docs, code and report hashes verified')
PY
